DO $$
DECLARE
    unexpected integer;
    changed integer;
BEGIN
    SELECT count(*) INTO unexpected FROM fix f
    LEFT JOIN speed_reading.reading_questions q ON q.id = f.id
    WHERE q.id IS NULL OR NOT ((q.question_text IS NOT DISTINCT FROM f.from_question_text AND q.explanation IS NOT DISTINCT FROM f.from_explanation AND q.option_a IS NOT DISTINCT FROM f.from_option_a AND q.option_b IS NOT DISTINCT FROM f.from_option_b AND q.option_c IS NOT DISTINCT FROM f.from_option_c AND q.option_d IS NOT DISTINCT FROM f.from_option_d AND q.correct_answer IS NOT DISTINCT FROM f.from_correct_answer) OR (q.question_text IS NOT DISTINCT FROM f.to_question_text AND q.explanation IS NOT DISTINCT FROM f.to_explanation AND q.option_a IS NOT DISTINCT FROM f.to_option_a AND q.option_b IS NOT DISTINCT FROM f.to_option_b AND q.option_c IS NOT DISTINCT FROM f.to_option_c AND q.option_d IS NOT DISTINCT FROM f.to_option_d AND q.correct_answer IS NOT DISTINCT FROM f.to_correct_answer));
    IF unexpected <> 0 THEN
        RAISE EXCEPTION 'pool-texts-v1-fix1: % question(s) missing or edited by hand; nothing changed', unexpected;
    END IF;

    UPDATE speed_reading.reading_questions q
    SET question_text = f.to_question_text, explanation = f.to_explanation, option_a = f.to_option_a, option_b = f.to_option_b, option_c = f.to_option_c, option_d = f.to_option_d, correct_answer = f.to_correct_answer,
        updated_at = CURRENT_TIMESTAMP, updated_by = 'pool-texts-v1-fix1'
    FROM fix f WHERE q.id = f.id AND q.question_text IS NOT DISTINCT FROM f.from_question_text AND q.explanation IS NOT DISTINCT FROM f.from_explanation AND q.option_a IS NOT DISTINCT FROM f.from_option_a AND q.option_b IS NOT DISTINCT FROM f.from_option_b AND q.option_c IS NOT DISTINCT FROM f.from_option_c AND q.option_d IS NOT DISTINCT FROM f.from_option_d AND q.correct_answer IS NOT DISTINCT FROM f.from_correct_answer;
    GET DIAGNOSTICS changed = ROW_COUNT;
    RAISE NOTICE 'pool-texts-v1-fix1: % question(s) fixed, % already done', changed, 4 - changed;
END $$;

